function toast(text){if(activeMember&&activeMember.id!==net.self){activeMember.notice={text,id:++eventSerial};return;}$('toast').textContent=text;toastTime=3.8;}
function billboard(canvas,x,z,size=2,y=0){const mat=new THREE.SpriteMaterial({map:atlas.texture(canvas),transparent:true,alphaTest:.22,depthWrite:true,fog:true});const sprite=new THREE.Sprite(mat);sprite.center.set(.5,0);sprite.position.set(x,y,z);sprite.scale.set(size,size,1);scene.add(sprite);return sprite;}
function changeFrame(sprite,canvas){const map=atlas.texture(canvas);if(sprite.material.map!==map){sprite.material.map=map;sprite.material.needsUpdate=true;}}
function disposeWorld(){if(!scene)return;scene.traverse(o=>{if(o.isMesh)o.geometry?.dispose();if(o.material&&!Array.isArray(o.material))o.material.dispose();});}

function buildArchitecture(){
 if(levelVisuals){scene.remove(levelVisuals.group);levelVisuals.dispose();}
 levelVisuals=new LevelVisuals(world,atlas,themeIndex);architecture=levelVisuals.group;scene.add(architecture);
}
function objectBox(point,tileIndex,width,height,depth){const tile=atlas.frame('env-'+THEMES[themeIndex].id,tileIndex%4,Math.floor(tileIndex/4));const box=new THREE.Mesh(new THREE.BoxGeometry(width,height,depth),new THREE.MeshLambertMaterial({map:atlas.texture(tile),color:'#d2dcdf'}));box.position.set(point.x,(point.y??world.floor(point.x,point.z)??0)+height/2,point.z);scene.add(box);return box;}
function spawnActor(id,x,z,finalBrood=false,feetY){if(actors.filter(a=>a.hp>0).length>=(mode==='coop'?Math.max(1,net.members.length)*160:200))return null;const a=makeActor(id,x,z);a.groundY=world.floor(x,z,feetY)??feetY??0;a.sprite=billboard(atlas.actor(id,'idle',0),x,z,ACTORS[id].size,a.groundY);actors.push(a);return a;}
function addPickup(kind,id,x,z,delay=0,amount=0){
 const index=kind==='health'||kind==='scrap'?7:WEAPON_BY_ID[id].index,row=kind==='ammo'?1:0,y=world.floor(x,z)??0;
 const p={kind,gun:id,x,z,y,age:0,delay,amount,taken:false};
 p.sprite=billboard(atlas.frame('pickups',index,row),x,z,kind==='gun'?1.65:1.05,y+.18);
 if(kind==='scrap'){changeFrame(p.sprite,atlas.frame('oldLoot',3,1));p.sprite.material.color.set('#efbd70');}
 if(kind==='health')changeFrame(p.sprite,atlas.frame('oldLoot',0,2));pickups.push(p);return p;
}
function setup(seed=2709,index=0,keep=false,layoutVersion=3){
 const retained=keep?arsenal:null;sfx.stopAll();pendingShots=[];stepTimer=0;disposeWorld();baseSeed=seed;chapterIndex=index%CHAPTERS.length;mode=net.active?net.mode:'solo';const chapter=CHAPTERS[chapterIndex];themeIndex=chapter.theme;const theme=THEMES[themeIndex];world=makeWorld(seed+chapterIndex*911,themeIndex,layoutVersion===3?chapterIndex:null);
 scene=new THREE.Scene();scene.background=new THREE.Color(theme.fog);scene.fog=new THREE.Fog(theme.fog,45,145);architecture=null;levelVisuals=null;lights=new CombatLights(scene);buildArchitecture();
 player={...world.start,vy:0,yaw:0,pitch:0,hp:100,grounded:true,safe:{...world.start},hurtCooldown:0};arsenal=retained||new Arsenal();visor=new VisorState();radio=new Radio();mission=initialMission();actors=[];nests=[];cases=[];pickups=[];effects=[];projectiles=[];waves=[];bridgeAdded=false;ending=false;radioId=null;elapsed=0;storyEvents=new Set();mapOpen=false;score=keep?score:entryScore;netEvents=[];lastEvent=eventSerial=0;matchTime=0;saveTimer=0;toastTime=0;tasks=new MissionTasks(world,chapterIndex);guide=new RouteGuide(world);compass=new CompassContacts(world);taskVisuals=new TaskVisuals(scene,tasks,atlas,levelVisuals);
 if(!keep&&entryLoadout){arsenal.slots=structuredClone(entryLoadout.slots);arsenal.selected=entryLoadout.selected;}
 infestation=new Infestation(world,{enabled:mode!=='ffa'});growthVisuals=new InfestationVisuals(scene,infestation,atlas);
 stationVisuals=new StationVisuals(scene,installStationProps(world,[...tasks.nodes,...infestation.patches]),atlas);stationVisuals.update(0,player,null,world);
 entryScore=score;entryLoadout={slots:structuredClone(arsenal.slots),selected:arsenal.selected};
 const previous=campaign.at(-1),purgedBefore=previous?.choices.some(c=>c.id==='purge'&&c.value==='purge');
 for(const p of mode==='ffa'?[]:world.nests){const n=makeNest(p.x,p.z);n.y=p.y;n.variant=p.variant;n.budget=purgedBefore?3:5;n.sprite=billboard(nestFrame(n),n.x,n.z,n.variant===2?3.45:2.9,n.y);nests.push(n);}
 if(mode!=='ffa'){const machine=makeNest(world.fabricator.x,world.fabricator.z,true);machine.y=world.fabricator.y;machine.budget=4;machine.sprite=billboard(atlas.frame('legacyProps',0,0),machine.x,machine.z,3,machine.y);nests.push(machine);}
 decorations=[];for(const r of world.rooms){if(r.id==='arrival'){for(const dx of[-7,7]){const sprite=billboard(atlas.frame('legacyProps',0,5),r.center.x+dx,r.center.z,3,r.y);decorations.push({sprite,row:5});}}else if(r.id==='east'||r.id==='upper'){const sprite=billboard(atlas.frame('legacyProps',0,1),r.center.x+10,r.center.z+7,3,r.y);decorations.push({sprite,row:1});}}
 for(const c of world.cases){const b={...c,open:false,age:0,dispensed:false};b.sprite=billboard(atlas.frame('pickups',0,2),b.x,b.z,2.5,b.y);cases.push(b);}
 for(const p of world.supplies)addPickup(p.kind,p.gun,p.x,p.z,0,p.amount||0);
 addPickup('ammo','bolt',world.start.x-6,world.start.z-10);
 for(const e of encounterPlan(world,chapterIndex,net.members.length||1,mode))spawnActor(e.type,e.x,e.z,false,e.y);
 if(previous&&!purgedBefore&&mode!=='ffa'){const r=world.rooms.find(r=>r.id==='hall');spawnActor('beetle',r.center.x+9,r.center.z+5);spawnActor('spitter',r.center.x-9,r.center.z-5);}
 recordTerminal=objectBox(world.control,12,1.8,2.2,.7);purgeTerminal=objectBox(world.purge,12,1.7,2.1,.65);exitDoor=objectBox(world.exit,8,4,3.7,.35);
 for(const [point,text]of [[world.control,'RECOVERY ARCHIVE\nACCESS RECORD'],[world.purge,'RESEARCH BANK\nARCHIVE CONTROL']]){const screen=levelVisuals.terminal(text,point.x,point.y+1.35,point.z+.36,1.5);scene.add(screen);}
 $('sector-name').textContent=String(chapterIndex+1).padStart(2,'0')+' / '+chapter.title.toUpperCase();$('theme').value=chapterIndex;$('pilot-name').textContent=PILOTS[pilot].name.toUpperCase();
 decals=[];initializeCrew(keep);if(mode==='ffa'){for(const g of world.gates)g.open=true;for(const c of cases)c.locked=false;for(const r of world.rooms)addPickup('health',null,r.center.x,r.center.z,0,35);}
 camera.position.set(player.x,player.y+1.65,player.z);camera.rotation.set(0,0,0);drawHud();
}
function nestFrame(n){
 if(n.variant===1)return atlas.frame('legacyProps',Math.floor(n.age*6)%4,2);
 if(n.variant===2)return atlas.frame('legacyProps',Math.floor(n.age*6)%4,3);
 const row=n.state==='husk'?3:n.state==='rupture'?2:n.state==='spawn'?1:0,col=n.state==='husk'?7:n.state==='rupture'?Math.min(7,Math.floor(n.age/.9*8)):Math.floor(n.age*8)%8;return atlas.frame('pod',col,row);
}
function story(event){if(storyEvents.has(event))return;storyEvents.add(event);radio.send({...storyMessage(chapterIndex,event,{results:campaign,mission}),priority:true});}

function particleBurst(x,y,z,color,count=24,power=4){emitVisual('particles',{x,y,z,color,count,power});if(count>20)lights?.flash({x,y,z},color,6,.3,13);
 for(let i=0;i<Math.ceil(count*.62);i++){const size=.17+world.random()*.3,mesh=effectSprite(atlas,7,Math.floor(world.random()*8),x,y,z,size,color);mesh.material.rotation=world.random()*Math.PI*2;scene.add(mesh);effects.push({mesh,life:.45+world.random()*.65,age:0,vfx:7,offset:i%8,vx:(world.random()-.5)*power,vy:world.random()*power*.9,vz:(world.random()-.5)*power,gravity:7});}
 while(effects.length>320)removeEffect(effects.shift());
}
function ring(x,z,color,max=6,duration=.7,y=.05){emitVisual('ring',{x,z,color,max,duration,y});const ground=world.floor(x,z)??0,area=max>=3,row=color.includes('c4')||color.includes('ba')||color.includes('d8')?3:color.includes('ad')||color.includes('b5')?1:2,mesh=area?areaEffect(atlas,x,ground+y,z,color,row):effectRing(atlas,x,ground+y,z,color);scene.add(mesh);lights?.flash({x,y:ground+1,z},color,11,duration,12);effects.push({mesh,age:0,life:duration,ring:true,vfx:area?undefined:4,max,area,color});}
function beam(from,to,color,life=.14,width=.035){emitVisual('beam',{from:{x:from.x,y:from.y,z:from.z},to:{x:to.x,y:to.y,z:to.z},color,life,width});lights?.flash(from,color,8,life,16);lights?.flash(to,color,4,life,9);const mesh=effectBeam(atlas,from,to,color,Math.max(.09,width*5),camera);scene.add(mesh);effects.push({mesh,life,age:0,vfx:5});}
function removeEffect(e){scene.remove(e.mesh);e.mesh.traverse(o=>{o.geometry?.dispose();o.material?.dispose();});}
function damageGrowth(p,damage,flame=false){
 const alive=!p.dead;infestation.hit(p.id,damage,flame);if(!alive)return;
 particleBurst(p.x+p.nx*.2,p.y,p.z+p.nz*.2,GROWTH_COLORS[p.type],p.dead?26:6,p.dead?5:2);
 if(p.dead){spriteBurst(p.x+p.nx*.3,p.y,p.z+p.nz*.3,p.type===3?1:p.type===2?2:0,2.2);floorSplatter(p.x+p.nx*.7,p.z+p.nz*.7,GROWTH_GOO[p.type],2);sfx.play(flame?'explosion':'acid',{position:p,gain:.55});if(Math.hypot(player.x-p.x,player.z-p.z)<4)visor.stain(world.random()*999,true,GROWTH_GOO[p.type]);}
 growthVisuals.update();
}
function updateWaveVisual(w){if(w.age<0)return;if(!w.mesh){w.mesh=areaEffect(atlas,w.x,w.y+.08,w.z,w.color,w.row??2);scene.add(w.mesh);}animateArea(w.mesh,atlas,w.radius,w.age,Math.min(1,(10.5-w.radius)/1.5));}
function updateLights(dt){
 const sources=[];
 for(const w of [...waves.filter(w=>w.age>=0),...effects.filter(e=>e.area).map(e=>({x:e.mesh.position.x,y:e.mesh.position.y,z:e.mesh.position.z,radius:e.age/e.life*e.max,color:e.color}))]){
  const angle=Math.atan2(player.z-w.z,player.x-w.x);for(const offset of[-.45,.45])sources.push({x:w.x+Math.cos(angle+offset)*w.radius,y:w.y+.8,z:w.z+Math.sin(angle+offset)*w.radius,color:w.color,strength:13,radius:12,kind:'area'});
 }
 for(const e of effects)if(e.flame)sources.push({...e.mesh.position,color:'#ff9e38',strength:11*(1-e.age/e.life),radius:10,kind:'flame'});
 lights.update(dt,projectiles,sources,player);
}
function damagePlayer(amount,goo=false,color='green'){const m=activeMember||crew.find(m=>m.id===net.self);if(!m||ending||m.player.hp<=0||m.player.hurtCooldown>0)return;damageMember(m,amount,null,goo,color);}
function spawnBrood(n,count,finalBrood=false){for(let i=0;i<count*(mode==='coop'?crew.length:1);i++){let x=n.x,z=n.z;for(let tries=0;tries<12;tries++){const ang=world.random()*Math.PI*2,rad=1+world.random()*1.1,nx=n.x+Math.cos(ang)*rad,nz=n.z+Math.sin(ang)*rad;if(world.canMove(nx,nz,.5,n.y??n.groundY??0)&&world.floor(nx,nz,n.y??n.groundY??0)!==null){x=nx;z=nz;break;}}let type=n.machine?(i%2?'spider':'drone'):n.variant===2?(i%2?'bat':'leech'):n.variant===1?(i%2?'worm':'crawler'):i%3===2?'spitter':'beetle';if((INTRODUCTIONS[type]||0)>chapterIndex)type=n.machine&&chapterIndex>=2?'drone':i%2?'crawler':'beetle';spawnActor(type,x,z,finalBrood,n.y??n.groundY??0);}}
function spriteBurst(x,y,z,row,size=3){emitVisual('burst',{x,y,z,row,size});lights?.flash({x,y,z},row===1?'#ff983f':'#77dfe9',9,.3,16);const mesh=billboard(atlas.frame('bursts',0,row),x,z,size,y-size*.5);mesh.material.depthWrite=false;mesh.material.alphaTest=.04;effects.push({mesh,life:.5,age:0,burst:row});}
function splatterFrame(color,variant=0){return color==='green'?atlas.frame('splatter',variant%4,Math.floor(variant/4)%4):atlas.frame('coloredSplatter',variant%4,['cyan','amber','violet','oil'].indexOf(color));}
function floorSplatter(x,z,color,size=2){emitVisual('decal',{x,z,color,size});const mesh=new THREE.Mesh(new THREE.PlaneGeometry(size,size),new THREE.MeshBasicMaterial({map:atlas.texture(splatterFrame(color,Math.floor(world.random()*16))),transparent:true,alphaTest:.1,depthWrite:false,opacity:.76}));mesh.rotation.set(-Math.PI/2,0,world.random()*Math.PI*2);mesh.position.set(x,(world.floor(x,z)??0)+.018+decals.length*.0001,z);scene.add(mesh);decals.push(mesh);if(decals.length>80){const old=decals.shift();scene.remove(old);old.geometry.dispose();old.material.dispose();}}
function enemyHit(a,point,lethal=false){
 emitVisual('gore',{actor:{type:a.type},point,lethal});
 const row=GORE_ROWS[a.type],size=lethal?ACTORS[a.type].size*1.8:1.0,life=lethal?.85:.29;
 const mesh=billboard(atlas.frame('originalGore',0,row),point.x,point.z,size,point.y-size*.48);mesh.material.depthWrite=false;mesh.material.alphaTest=.04;effects.push({mesh,life,age:0,gore:row,lethal});
 const count=lethal?(ACTORS[a.type].tier==='BOSS'?18:11):5,toPlayer=aimDirection(point,{x:player.x,y:player.y+1.3,z:player.z});
 for(let i=0;i<count;i++){
  const fragment=billboard(atlas.frame('originalGore',5+i%3,row),point.x,point.z,lethal?.35+world.random()*.65:.2+world.random()*.3,point.y);
  fragment.center.set(.5,.5);fragment.material.depthWrite=false;fragment.material.rotation=world.random()*6.28;
  effects.push({mesh:fragment,life:.45+world.random()*.8,age:0,vx:(world.random()-.5)*5+toPlayer.x*2,vy:1+world.random()*4,vz:(world.random()-.5)*5+toPlayer.z*2,gravity:9});
 }
 while(effects.length>320)removeEffect(effects.shift());
}
function creatureBurst(a){const g=GORE[a.type];enemyHit(a,{x:a.x,y:(a.groundY||0)+ACTORS[a.type].size*.48,z:a.z},true);floorSplatter(a.x,a.z,g.color,Math.min(5,ACTORS[a.type].size*1.8));if(Math.hypot(a.x-player.x,a.z-player.z)<5)for(let i=0;i<3;i++)visor.stain(world.random()*999,true,g.color);}

function combatEvent(e){
 if(e.type==='spawn'){spawnBrood(e.nest,e.count);particleBurst(e.nest.x,(e.nest.y||0)+.8,e.nest.z,e.nest.machine?'#8ccfd9':'#99cb36',15,2);return;}
 if(e.type==='nestBurst'){
  if(world.random()<.65)addPickup('scrap',null,e.nest.x,e.nest.z,1,25+Math.floor(world.random()*5)*10);
  spawnBrood(e.nest,e.count,true);mission.nestsDestroyed++;particleBurst(e.nest.x,(e.nest.y||0)+1.5,e.nest.z,e.nest.machine?'#f3ad51':'#a3d12d',75,10);if(e.nest.machine)spriteBurst(e.nest.x,(e.nest.y||0)+1.5,e.nest.z,1,4);ring(e.nest.x,e.nest.z,e.nest.machine?'#b4ddf4':'#adc62b',5,1);shake=.28;sfx.play('explosion',{position:e.nest,gain:1.15});
  floorSplatter(e.nest.x,e.nest.z,e.nest.machine?'oil':'green',4.5);if(Math.hypot(player.x-e.nest.x,player.z-e.nest.z)<8){for(let i=0;i<8;i++)visor.stain(world.random()*999,true,e.nest.machine?'oil':'green');toast('POD RUPTURE');}return;
 }
 if(e.type==='killed'){const a=e.actor;creatureBurst(a);sfx.play(ACTORS[a.type].family==='MACHINE'?'metal':'acid',{position:a,gain:.9,minInterval:.04});if(ACTORS[a.type].splits){spawnActor('crawler',a.x+.7,a.z,true);spawnActor('crawler',a.x-.7,a.z,true);}for(const [i,drop]of rollLoot(world.random,ACTORS[a.type].tier).entries())addPickup(drop.kind,drop.kind==='ammo'?arsenal.selected:null,a.x+(i-1)*.6,a.z,.7,drop.amount||0);return;}
 if(e.type==='damage'){const target=crew.find(m=>m.id===e.targetId)||crew.find(m=>m.id===net.self);if(target)damageMember(target,e.amount);return;}
 if(e.type==='impact'){particleBurst(e.actor.x,(e.actor.groundY||0)+1,e.actor.z,'#b7dfe0',32,7);ring(e.actor.x,e.actor.z,'#83cede',3);return;}
 if(e.type==='tell'){if(['rail','charge'].includes(e.kind)){const a=e.actor;beam({x:a.x,y:(a.groundY||0)+.1,z:a.z},{...a.target,y:(a.groundY||0)+.1},'#e1a470',a.duration,.012);}return;}
 if(e.type==='attack')attack(e.actor,e.kind,e.target);
}
function shootProjectile(a,target,angle=0,speed=9,color='#bada49',radius=.18){
 const d=ACTORS[a.type],row=d.family==='MACHINE'||a.type==='jelly'?2:a.type==='bomber'||a.type==='crawler'?3:d.blood==='violet'?1:0;
 const dir=aimDirection({x:a.x,y:(a.groundY||0)+1.1,z:a.z},target),cos=Math.cos(angle),sin=Math.sin(angle),vx=(dir.x*cos-dir.z*sin)*speed,vz=(dir.x*sin+dir.z*cos)*speed;
 const mesh=effectSprite(atlas,row,0,a.x,(a.groundY||0)+1.1,a.z,radius*4.6+.45);scene.add(mesh);
 projectiles.push({id:++projectileSerial,mesh,row,x:a.x,y:(a.groundY||0)+1.1,z:a.z,vx,vy:dir.y*speed,vz,age:0,life:5,damage:d.damage,color,radius,goo:d.family==='ALIEN',gooColor:GORE[a.type].color});
}
