 if(w.mode!=='flame')beam(muzzle,hit.point,w.color,.14,w.mode==='pierce'?.09:.025);shotTracer(muzzle,hit.point,w);sfx.weapon(w.id,activeMember&&activeMember.id!==net.self?{position:player}:{});emitVisual('sound',{gun:w.id,position:{x:player.x,y:player.y+1,z:player.z},shooter:(activeMember||localCrew()).id});
 if(hit.entity){hitTime=.16;if(hit.kind==='player'){damageMember(hit.entity,w.damage,(activeMember||localCrew()).id);particleBurst(hit.point.x,hit.point.y,hit.point.z,PILOTS[hit.entity.pilot].color,8,3);}else if(hit.kind==='nest')damageNest(hit.entity,w.damage,combatEvent);else if(hit.kind==='growth')damageGrowth(hit.entity,w.damage,w.mode==='flame');else{hurtActor(hit.entity,w.damage,w.mode,combatEvent);enemyHit(hit.entity,hit.point);sfx.play(ACTORS[hit.entity.type].family==='MACHINE'?'metal':'impact',{position:hit.point,gain:.45,minInterval:.06});}if(hit.kind==='nest'){particleBurst(hit.point.x,hit.point.y,hit.point.z,hit.entity.machine?'#efa565':'#98cf47',9,2);spriteBurst(hit.point.x,hit.point.y,hit.point.z,w.mode==='freeze'?3:w.mode==='chain'?2:w.mode==='blast'?1:0,w.mode==='blast'?3:1);}}
