function nearestInteraction(){if(player.hp<=0)return null;let best=null,bestD=3.8;const consider=(kind,target,x,z,y,ignoreWall=false)=>{const d=Math.hypot(player.x-x,player.z-z,player.y-y);if(d<bestD&&(ignoreWall||world.los(player.x,player.z,x,z,player.y+1,y+1))){best={kind,target};bestD=d;}};
 for(const m of crew)if(m.player.down&&m.player!==player)consider('revive',m,m.player.x,m.player.z,m.player.y);
 for(const n of tasks?.nodes||[])if(mode!=='ffa'&&(tasks.interactable?.(n)??tasks.visible(n)))consider('task',n,n.x,n.z,n.y);
 for(const c of cases)if(!c.open)consider('case',c,c.x,c.z,c.y);
 if(mode!=='ffa'&&!mission.record)consider('record',recordTerminal,world.control.x,world.control.z,world.control.y);
 if(mode!=='ffa'&&!mission.choices.some(c=>c.id==='purge'))consider('purge',purgeTerminal,world.purge.x,world.purge.z,world.purge.y);
 for(const t of mode==='ffa'?[]:world.switches.filter(t=>t.timedGate||world.puzzle.required))consider('switch',t,t.x,t.z,t.y);
 if(mode!=='ffa'&&!world.accessCard.taken){const t=world.accessCard;consider('key',t,t.x,t.z,t.y);}
 for(const g of world.gates)if(!g.open)consider('gate',g,g.x,g.z,g.y,true);
 if(mode!=='ffa')consider('exit',exitDoor,world.exit.x,world.exit.z,world.exit.y);return best;
}
function interact(){if(net.active&&net.role==='guest'){net.action('interact');return true;}const i=nearestInteraction();if(!i)return false;
 if(i.kind==='revive')return true;
 if(i.kind==='task'){const result=tasks.use(i.target.id);toast(result.message||'');sfx.ui(!result.wrong);if(result.changed)saveCampaign(false);return result.accepted;}
 if(i.kind==='switch'){const result=world.useSwitch(i.target.id);toast(result.message);sfx.ui(!result.wrong);return result.accepted;}
 if(i.kind==='key'){world.accessCard.taken=true;toast('BLUE ACCESS CARD RECOVERED');sfx.play('pickup',{bus:'ui'});return true;}
 if(i.kind==='gate'){const result=world.useGate(i.target.id,player);toast(result.message);sfx.ui(result.accepted);return result.accepted;}
 if(i.kind==='case'){const c=i.target;if(c.locked&&mission.power!=='armory'){toast('ARMORY CASE SEALED · ROUTE POWER AT CONTROL');return false;}c.open=true;sfx.play('reload',{bus:'foley',gain:1,rate:.65});toast('CASE OPENING · '+WEAPON_BY_ID[c.gun].name);return true;}
 if(i.kind==='record'){mission.record=true;storyEvents.add('record');radio.send({...POWER,speaker:'ROOK',chapter:CHAPTERS[chapterIndex].title,text:storyMessage(chapterIndex,'record',{results:campaign,mission}).text+'\n'+POWER.text});toast('ACCESS RECORD RECOVERED');return true;}
 if(i.kind==='purge'){radio.send({...PURGE,speaker:'ROOK',chapter:CHAPTERS[chapterIndex].title,text:mission.record?'The copied ledger is secured. The live research bank shares power with the hatcheries. Preserve the observations, or purge the sources?':CHAPTERS[chapterIndex].discovery+' Preserve the research, or purge the sources?'});return true;}
 if(i.kind==='exit'){const boss=actors.find(a=>ACTORS[a.type].tier==='BOSS'&&a.hp>0);if(!mission.record||boss||!world.puzzle.solved||!tasks.solved){toast(!tasks.solved?tasks.objective():!mission.record?'RECOVER THE ACCESS RECORD':!world.puzzle.solved?'RESTORE THE RELAY CIRCUIT':'DEFEAT THE SECTOR GUARDIAN');return false;}finish(true);return true;}
}

function choose(index){if(net.active&&net.role==='guest'){net.action('choice'+index);return;}const decision=radio.active?.decision,value=radio.active?.choices?.[index]?.value,result=radio.choose(index,mission);if(!result.accepted)return;story(decision==='power'?'power-'+value:value);radioId=null;sfx.ui();saveTimer=30;if(mission.power==='maintenance'&&!bridgeAdded){world.bridge();buildArchitecture();bridgeAdded=true;}if(mission.purged&&!mission.purgeApplied){mission.purgeApplied=true;for(const n of nests.filter(n=>!n.machine&&n.hp>0))damageNest(n,10000,combatEvent);toast('PURGE · Nests ruptured. Final broods remain. Research lost.');}}
function finish(success){
 if(ending)return;ending=true;paused=true;shooting=false;document.exitPointerLock?.();$('ending').hidden=false;$('pause').hidden=true;
 $('ending-label').textContent=success?'RECOVERY COMPLETE':'SIGNAL LOST';$('ending-title').textContent=success?(chapterIndex===CHAPTERS.length-1?'CONTRACT CLOSED':'EXTRACTED'):'MISSION FAILED';
 const choice=mission.power==='armory'?'ARMORY POWERED':mission.power==='maintenance'?'BRIDGE RESTORED':'POWER UNCHANGED';
 const research=mission.purged?'RESEARCH LOST':mission.choices.some(c=>c.id==='purge')?'RESEARCH PRESERVED':'ARCHIVE UNRECOVERED';
 $('outcome').textContent=success?CHAPTERS[chapterIndex].exit+'\n'+`${choice} · ${research} · SCRAP SCORE ${score}`:'SCRAP RECOVERED '+score;
 $('next').textContent=success?'NEXT SECTOR':'RETRY';mission.complete=success;
 if(success&&mode==='pvpve'){const winner=activeMember||localCrew();winner.score+=1000;if(winner.id===net.self)score=winner.score;$('ending-title').textContent=PILOTS[winner.pilot].name.toUpperCase()+' EXTRACTED';$('outcome').textContent=crew.slice().sort((a,b)=>b.score-a.score).map(m=>PILOTS[m.pilot].name.toUpperCase()+' / '+m.score+' SCRAP / '+m.frags+' FRAGS').join('\n');$('next').textContent='NEXT RECOVERY';return;}
 if(mode==='ffa')return;
 if(success){campaign=campaign.filter(c=>c.chapter!==chapterIndex);campaign.push({chapter:chapterIndex,theme:THEMES[themeIndex].id,choices:[...mission.choices],purgeBeforeRecord:mission.purgeBeforeRecord===true,nestsDestroyed:mission.nestsDestroyed,score});if(chapterIndex===CHAPTERS.length-1){$('outcome').textContent+='\n'+campaignEnding(campaign);$('next').textContent='NEW RECOVERY';}saveCampaign(false,true);}
}
function start(keep=false){if(net.active&&net.role==='guest')return;if(net.role==='host')net.start({seed:Number($('seed').value)||2709,chapter:Number($('theme').value),keep});sfx.unlock();sfx.setPaused(false);pilot=$('pilot').value;setup(Number($('seed').value)||2709,Number($('theme').value),keep);$('menu').hidden=true;$('pause').hidden=true;$('ending').hidden=true;document.body.classList.remove('menu-open');running=true;paused=false;if(mode!=='ffa')story('intro');syncMissionProgress();saveCampaign(false);controller.suspend();lockMouse();sfx.ui();}
function pause(){if(!running||ending)return;controller.suspend();paused=true;shooting=false;keys.clear();sfx.setPaused(true);$('pause').hidden=false;document.exitPointerLock?.();}
function resume(){sfx.unlock();sfx.setPaused(false);paused=false;$('pause').hidden=true;controller.suspend();controllerMenu.clear();lockMouse();}

