  if(!n.machine){changeFrame(n.sprite,nestFrame(n));if(n.variant){n.sprite.material.color.set(n.state==='husk'?'#4b3a45':n.state==='hurt'?'#ffc77b':'#ffffff');n.sprite.scale.y=n.state==='husk'?.65:n.variant===2?3.45:2.9;}}
