function advanceEffects(dt){ for(let i=effects.length-1;i>=0;i--){const e=effects[i];e.age+=dt;if(e.age>=e.life){removeEffect(e);effects.splice(i,1);continue;}if(e.tracer){const t=Math.min(1,e.age/e.life);e.mesh.position.set(e.from.x+(e.to.x-e.from.x)*t,e.from.y+(e.to.y-e.from.y)*t,e.from.z+(e.to.z-e.from.z)*t);}
 if(e.area){animateArea(e.mesh,atlas,e.age/e.life*e.max,e.age,Math.min(1,(e.life-e.age)*4));continue;}if(e.flame){changeFrame(e.mesh,atlas.frame('areaVfx',Math.min(7,Math.floor(e.age/e.life*8)),0));const size=.65+e.age/e.life*1.8;e.mesh.scale.set(size,size,1);e.mesh.material.opacity=Math.min(1,(e.life-e.age)*7);continue;}if(e.vfx!==undefined){changeFrame(e.mesh,atlas.frame('attackVfx',e.ring?Math.min(7,Math.floor(e.age/e.life*8)):(Math.floor(e.age*18)+(e.offset||0))%8,e.vfx));if(e.mesh.userData.beam)orientBeam(e.mesh,camera);}if(e.gore!==undefined){changeFrame(e.mesh,atlas.frame('originalGore',Math.min(7,Math.floor(e.age/e.life*8)),e.gore));}else if(e.deathBurst!==undefined){changeFrame(e.mesh,atlas.frame('deathBursts',Math.min(7,1+Math.floor(e.age/e.life*7)),e.deathBurst));}else if(e.burst!==undefined){changeFrame(e.mesh,atlas.frame('bursts',Math.min(3,Math.floor(e.age/e.life*4)),e.burst));}else if(e.ring){e.mesh.scale.setScalar(.1+e.age/e.life*e.max*2.6);e.mesh.material.opacity=1-e.age/e.life;}else if(e.vx!==undefined){e.vy-=e.gravity*dt;e.mesh.position.x+=e.vx*dt;e.mesh.position.y+=e.vy*dt;e.mesh.position.z+=e.vz*dt;e.mesh.material.rotation+=dt*4;e.mesh.material.opacity=1-e.age/e.life;const floor=(world.floor(e.mesh.position.x,e.mesh.position.z,e.mesh.position.y)??-22)+.04;if(e.mesh.position.y<floor){e.mesh.position.y=floor;e.vy=0;e.vx*=.9;e.vz*=.9;}}else e.mesh.material.opacity=1-e.age/e.life;}
}

function localCrew(){return crew.find(m=>m.id===net.self)||crew[0];}
function livingCrew(){return crew.filter(m=>m.player.hp>0);}
function localInput(){const enabled=!paused&&!ending&&player?.hp>0,pad=controller.state,h=pad.held;return{forward:enabled?Math.max(-1,Math.min(1,Number(keys.has('KeyW'))-Number(keys.has('KeyS'))-pad.move.y)):0,strafe:enabled?Math.max(-1,Math.min(1,Number(keys.has('KeyD'))-Number(keys.has('KeyA'))+pad.move.x)):0,sprint:enabled&&(keys.has('ShiftLeft')||!!h[PAD.sprint]),jump:enabled&&(keys.has('Space')||pad.jump),revive:enabled&&(keys.has('KeyE')||!!h[PAD.use]),fire:enabled&&(shooting||!!h[PAD.fire]),yaw:player?.yaw||0,pitch:player?.pitch||0,weapon:arsenal?.selected||'bolt',paused:!enabled};}
function inputFor(id){return id===net.self?localInput():net.inputFor(id,performance.now());}
function initializeCrew(keep=false){const old=new Map(crew.map(m=>[m.id,m]));crew=[];for(const [i,record]of(net.active?net.members:[{id:net.self,pilot}]).entries()){const own=record.id===net.self,p={...world.start,x:world.start.x+(i%2)*2,z:world.start.z+Math.floor(i/2)*2,vy:0,yaw:0,pitch:0,hp:100,grounded:true,safe:{...world.start},hurtCooldown:2};const m={...record,player:own?player:p,arsenal:own?arsenal:new Arsenal(),visor:own?visor:new VisorState(),score:own?score:0,frags:0,deaths:0,walkAge:0,actions:{}};if(own){pilot=record.pilot;$('pilot').value=pilot;}if(mode==='ffa'||mode==='pvpve'){const spawn=respawnPoint(world,crew,world.random);Object.assign(m.player,spawn,{safe:{...spawn}});}if(old.get(record.id)&&mode==='coop'&&keep){m.arsenal.slots=structuredClone(old.get(record.id).arsenal.slots);}crew.push(m);if(!own){m.sprite=billboard(atlas.frame('crew-'+m.pilot+'-bolt',0,0),m.player.x,m.player.z,2.6,m.player.y);}}
 $('save-game').hidden=net.active;$('restart').hidden=net.active;$('room-deploy').hidden=net.role!=='host';}
function withMember(m,fn){if(m===localCrew())return fn();const saved={player,arsenal,visor,score,activeMember};player=m.player;arsenal=m.arsenal;visor=m.visor;score=m.score;activeMember=m;try{return fn();}finally{m.score=score;({player,arsenal,visor,score,activeMember}=saved);}}
function damageMember(m,amount,attacker=null,goo=false,color='green'){if(!m||m.player.hp<=0||m.player.hurtCooldown>0||ending)return false;const died=hitPlayer(m,amount,{mode,attacker});if(goo)for(let i=0;i<3;i++)m.visor.stain(world.random()*999,true,color);if(m.id===net.self){damageFlash=.33;shake=.13;sfx.play('impact',{bus:'foley',gain:1.2});}if(died){if(attacker&&attacker!==m.id){const killer=crew.find(p=>p.id===attacker);if(killer){killer.frags++;killer.score+=100;if(killer.id===net.self)score=killer.score;}}emitVisual('burst',{x:m.player.x,y:m.player.y+1,z:m.player.z,row:2,size:2});if(mode==='solo')finish(false);}return died;}
function enemyTarget(a){return livingCrew().sort((m,n)=>Math.hypot(m.player.x-a.x,m.player.z-a.z,m.player.y-(a.groundY||0))-Math.hypot(n.player.x-a.x,n.player.z-a.z,n.player.y-(a.groundY||0)))[0];}
function collectPickup(m,p){const a=m.arsenal,player=m.player;if(p.kind==='health'){if(player.hp>=100)return false;player.hp=Math.min(100,player.hp+(p.amount||25));}else if(p.kind==='scrap'){m.score+=p.amount||25;if(m.id===net.self)score=m.score;}else if(p.kind==='gun'){a.unlock(p.gun);if(mode==='coop')for(const other of crew)if(other!==m){const old=other.arsenal.selected;other.arsenal.unlock(p.gun);other.arsenal.equip(old);}}else a.addAmmo(p.gun,WEAPON_BY_ID[p.gun].mag*2);p.taken=true;p.respawnAt=p.age+30;p.sprite.visible=false;if(m.id===net.self){toast(p.kind==='gun'?'ACQUIRED / '+WEAPON_BY_ID[p.gun].name:p.kind==='scrap'?'+'+(p.amount||25)+' SCRAP':p.kind==='health'?'SUIT RESTORED':'AMMO RECOVERED');sfx.play('pickup',{bus:'ui'});}saveCampaign(false);return true;}
function reloadWeapon(){if(net.active&&net.role==='guest'){net.action('reload');return;}if(player.hp>0&&!visor.active&&arsenal.startReload())sfx.reload(arsenal.selected,0);}
function wipeVisor(){if(net.active&&net.role==='guest'){net.action('wipe');return true;}if(player.hp>0&&!arsenal.reload&&visor.wipe()){if(!activeMember)sfx.play('wipe',{bus:'foley'});return true;}return false;}
function updateCrewHost(dt){if(!crew.length)return;localCrew().score=score;for(const m of crew){if(m.id===net.self)continue;const input=inputFor(m.id);m.player.hurtCooldown=Math.max(0,m.player.hurtCooldown-dt);m.arsenal.update(dt);m.visor.update(dt);if(m.player.hp>0){if(Number.isFinite(input.yaw))m.player.yaw=input.yaw;if(Number.isFinite(input.pitch))m.player.pitch=input.pitch;const motion=movePlayer(m.player,world,dt,input);if(motion.fell)damageMember(m,18);m.moving=motion.moving;if(m.moving)m.walkAge+=dt;m.arsenal.equip(input.weapon);withMember(m,()=>{for(const [key,value]of Object.entries(input.actions||{})){if(value>(m.actions[key]||0)){m.actions[key]=value;if(key==='interact')interact();if(key==='reload')reloadWeapon();if(key==='wipe')wipeVisor();if(key.startsWith('choice'))choose(Number(key.at(-1)));}}if(input.fire&&!input.paused)fire();});}}
 for(const event of updateRevives(crew,dt,world,inputFor)){emitVisual('burst',{x:crew.find(m=>m.id===event.target).player.x,y:crew.find(m=>m.id===event.target).player.y+1,z:crew.find(m=>m.id===event.target).player.z,row:3,size:2});toast('SALVAGER REVIVED');}
 for(const m of crew)if(m.player.dead&&mode!=='solo'){m.player.downAge=(m.player.downAge||0)+dt;if(m.player.downAge>4){const spawn=respawnPoint(world,crew,world.random);Object.assign(m.player,spawn,{hp:100,dead:false,down:false,vy:0,grounded:true,hurtCooldown:2,safe:{...spawn}});m.arsenal.reload=null;for(const w of WEAPONS)if(m.arsenal.slots[w.id].owned){m.arsenal.slots[w.id].mag=w.mag;m.arsenal.slots[w.id].reserve=Math.max(m.arsenal.slots[w.id].reserve,w.mag*2);}m.visor.stains=[];}}
}
function updateCrewSprites(dt){for(const m of crew){if(m.id===net.self||!m.sprite)continue;const p=m.player,frame=directionalFrame(p.yaw,player,p,m.walkAge,m.moving),spec=SPECS['crew-'+m.pilot+'-'+m.arsenal.selected],row=Math.floor(frame.direction/spec.cols)+(Math.floor(m.walkAge*9)%(spec.walkFrames||4))*(16/spec.cols);changeFrame(m.sprite,atlas.frame('crew-'+m.pilot+'-'+m.arsenal.selected,frame.direction%spec.cols,m.moving?row:Math.floor(frame.direction/spec.cols)));m.sprite.position.set(p.x,p.y,p.z);m.sprite.scale.set(2.6,p.hp>0?2.6:1.1,1);m.sprite.material.rotation=p.hp>0?0:Math.PI/2;m.sprite.material.opacity=p.dead?.4:1;m.sprite.material.color.set(p.down?'#bca38f':'#ffffff');}
 $('crew-status').textContent=net.active?crew.map(m=>PILOTS[m.pilot].name.toUpperCase()+' '+(m.player.down?'DOWN '+Math.round(m.player.revive/3*100)+'%':m.player.dead?'REDEPLOY':mode==='coop'?Math.ceil(m.player.hp)+'%':m.frags+' / '+m.deaths)).join('\n'):'';
}
function checkMatch(){if(ending)return;if(mode==='coop'&&crew.length&&livingCrew().length===0)finish(false);if(mode==='ffa'&&(crew.some(m=>m.frags>=20)||matchTime>=600)){finish(true);const sorted=[...crew].sort((a,b)=>b.frags-a.frags||a.deaths-b.deaths);$('ending-title').textContent=PILOTS[sorted[0].pilot].name.toUpperCase()+' WINS';$('outcome').textContent=sorted.map(m=>PILOTS[m.pilot].name.toUpperCase()+' / '+m.frags+' FRAGS / '+m.deaths+' DEATHS').join('\n');$('next').textContent='REMATCH';}if(net.active&&net.role==='guest')$('next').hidden=true;}
function navigationGoal(){if(mode==='ffa')return livingCrew().filter(m=>m.id!==net.self).sort((a,b)=>Math.hypot(a.player.x-player.x,a.player.z-player.z)-Math.hypot(b.player.x-player.x,b.player.z-player.z))[0]?.player;if(!tasks.solved)return tasks.goal(player);if(!world.accessCard.taken)return world.accessCard;if(!world.puzzle.solved)return world.switches.find(s=>s.index===world.puzzle.order[world.puzzle.input.length]);if(!mission.record)return world.control;const gate=world.gates.find(g=>g.id==='security'&&!g.open);if(gate)return gate;const boss=actors.find(a=>ACTORS[a.type].tier==='BOSS'&&a.hp>0);return boss?{x:boss.x,z:boss.z,y:boss.groundY}:world.exit;}
function updateNavigation(dt){
 const primary=navigationGoal();guide.update(player,primary,dt);
 const targets=compassTargets({world,tasks,mission,primary,cases,pickups,actors,crew,self:net.self,mode});
 compassView.render(compass.update(player,targets,dt,guide),player.yaw);
 const readout=$('route-guide');readout.textContent=guide.next?(guide.action.includes('LIFT')||guide.action.startsWith('RIDE')?guide.action:Math.ceil(guide.distance)+'m'+(guide.elevation>.45?' ↑':guide.elevation<-.45?' ↓':'')):'';
}

function emitVisual(kind,data){if(net.active&&net.role==='host'){netEvents.push({id:++eventSerial,kind,data});if(netEvents.length>80)netEvents.shift();}}
const dataOnly=o=>Object.fromEntries(Object.entries(o).filter(([k,v])=>!['sprite','mesh','waypoint'].includes(k)&&typeof v!=='function'));
function sceneState(){return{layoutVersion:world.layoutVersion,chapter:chapterIndex,seed:baseSeed,pilot,score,player:{...player},arsenal:{slots:arsenal.slots,selected:arsenal.selected},actors:actors.map(dataOnly),nests:nests.map(dataOnly),infestation:infestation.snapshot(),cases:cases.map(dataOnly),pickups:pickups.map(dataOnly),gates:world.gates.map(dataOnly),lifts:world.lifts.map(dataOnly),switches:world.switches.map(dataOnly),secrets:world.secrets.map(dataOnly),puzzle:world.puzzle,key:world.accessCard.taken,bridge:bridgeAdded,mission,tasks:tasks.snapshot(),campaign,storyEvents:[...storyEvents],radio:{active:radio.active,queue:radio.queue,seen:[...radio.seen],history:radio.history,elapsed:radio.elapsed},elapsed};}
function networkSnapshot(){localCrew().score=score;return{...sceneState(),crew:crew.map(m=>({id:m.id,pilot:m.pilot,player:{...m.player},arsenal:{slots:m.arsenal.slots,selected:m.arsenal.selected,reload:m.arsenal.reload,cooldown:m.arsenal.cooldown},visor:{stains:m.visor.stains,active:m.visor.active?{...m.visor.active,ids:[...m.visor.active.ids]}:null,palette:m.visor.palette,cooldown:m.visor.cooldown},score:m.score,frags:m.frags,deaths:m.deaths,walkAge:m.walkAge,moving:m.id===net.self?!!(localInput().forward||localInput().strafe):m.moving,notice:m.notice})),radio:{active:radio.active,elapsed:radio.elapsed,queue:radio.queue,seen:[...radio.seen],history:radio.history},projectiles:projectiles.map(dataOnly),waves:waves.map(dataOnly),events:netEvents,ending:ending?{success:mission.complete,title:$('ending-title').textContent,label:$('ending-label').textContent,text:$('outcome').textContent}:null,matchTime};}
function applyState(s){
 mission=structuredClone(s.mission);tasks.restore(s.tasks);infestation.restore(s.infestation);growthVisuals.update();world.accessCard.taken=!!s.key;Object.assign(world.puzzle,s.puzzle);for(const name of ['gates','lifts','switches','secrets'])for(let i=0;i<world[name].length;i++)if(s[name]?.[i])Object.assign(world[name][i],s[name][i]);if(s.bridge&&!bridgeAdded){world.bridge();buildArchitecture();bridgeAdded=true;}elapsed=s.elapsed||0;campaign=s.campaign||[];storyEvents=new Set(s.storyEvents||[]);if(s.radio){const dismissed=radio.dismissed;Object.assign(radio,{history:[],...s.radio});radio.seen=new Set(s.radio.seen||[]);radio.dismissed=dismissed;}
 const old=new Map(actors.map(a=>[a.id,a]));actors=(s.actors||[]).filter(a=>ACTORS[a.type]).map(raw=>{let a=old.get(raw.id);if(a)old.delete(raw.id);else{a=makeActor(raw.type,raw.x,raw.z);a.sprite=billboard(atlas.actor(raw.type,raw.state,raw.age,raw.duration),raw.x,raw.z,ACTORS[raw.type].size,raw.groundY);}Object.assign(a,raw);return a;});for(const a of old.values()){scene.remove(a.sprite);a.sprite.material.dispose();}
 for(let i=0;i<nests.length;i++)if(s.nests?.[i])Object.assign(nests[i],s.nests[i]);for(let i=0;i<cases.length;i++)if(s.cases?.[i])Object.assign(cases[i],s.cases[i]);
 for(let i=0;i<(s.pickups||[]).length;i++){const raw=s.pickups[i];let p=pickups[i];if(!p)p=addPickup(raw.kind,raw.gun,raw.x,raw.z,raw.delay,raw.amount);Object.assign(p,raw);p.sprite.visible=!p.taken;}while(pickups.length>(s.pickups||[]).length){const p=pickups.pop();scene.remove(p.sprite);p.sprite.material.dispose();}
}
function receiveFrame(s){if(!s||!running)return;applyState(s);matchTime=s.matchTime;for(const raw of s.crew||[]){const m=crew.find(m=>m.id===raw.id);if(!m)continue;const own=m.id===net.self,oldHp=m.player.hp,aim={yaw:m.player.yaw,pitch:m.player.pitch};Object.assign(m.player,raw.player);if(own&&!raw.player.dead&&!raw.player.down)Object.assign(m.player,aim);const desired=m.arsenal.selected;Object.assign(m.arsenal,raw.arsenal);if(own&&m.arsenal.slots[desired]?.owned)m.arsenal.selected=desired;m.score=raw.score;m.frags=raw.frags;m.deaths=raw.deaths;m.walkAge=raw.walkAge;m.moving=raw.moving;Object.assign(m.visor,raw.visor);if(m.visor.active)m.visor.active.ids=new Set(raw.visor.active.ids);if(own){score=m.score;if(oldHp>m.player.hp)damageFlash=.3;if(raw.notice&&raw.notice.id!==m.lastNotice){m.lastNotice=raw.notice.id;toast(raw.notice.text);}}}
 if(s.radio){const dismissed=radio.dismissed;Object.assign(radio,s.radio);radio.seen=new Set(s.radio.seen);radio.dismissed=dismissed;}
 const oldP=new Map(projectiles.map(p=>[p.id,p]));projectiles=(s.projectiles||[]).map(raw=>{let p=oldP.get(raw.id);if(p)oldP.delete(raw.id);else{p={mesh:effectSprite(atlas,raw.row,0,raw.x,raw.y,raw.z,raw.radius*4.6+.45)};scene.add(p.mesh);}Object.assign(p,raw);return p;});for(const p of oldP.values()){scene.remove(p.mesh);p.mesh.material.dispose();}
 const oldW=new Map(waves.map(w=>[w.id,w]));waves=(s.waves||[]).map(raw=>{const w=oldW.get(raw.id)||{};oldW.delete(raw.id);Object.assign(w,raw);return w;});for(const w of oldW.values())if(w.mesh)removeEffect(w);
 for(const e of s.events||[])if(e.id>lastEvent){lastEvent=e.id;const d=e.data;if(e.kind==='gore')enemyHit(d.actor,d.point,d.lethal);if(e.kind==='decal')floorSplatter(d.x,d.z,d.color,d.size);if(e.kind==='ring')ring(d.x,d.z,d.color,d.max,d.duration,d.y);if(e.kind==='enemySound')sfx.enemy(ACTORS[d.type],d.kind,d.position);if(e.kind==='beam')beam(d.from,d.to,d.color,d.life,d.width);if(e.kind==='tracer')shotTracer(d.from,d.to,WEAPON_BY_ID[d.gun]);if(e.kind==='particles')particleBurst(d.x,d.y,d.z,d.color,d.count,d.power);if(e.kind==='burst')spriteBurst(d.x,d.y,d.z,d.row,d.size);if(e.kind==='sound'){sfx.weapon(d.gun,{position:d.position});if(d.shooter===net.self)recoil=1;}}
 if(s.ending&&!ending){ending=true;paused=true;shooting=false;document.exitPointerLock?.();$('ending').hidden=false;$('pause').hidden=true;$('ending-title').textContent=s.ending.title;$('ending-label').textContent=s.ending.label;$('outcome').textContent=s.ending.text;$('next').hidden=true;}
}
function updateGuest(dt){elapsed+=dt;radio.update(dt);arsenal.update(dt);wipePose=visor.update(dt);recoil=Math.max(0,recoil-dt*8);damageFlash=Math.max(0,damageFlash-dt);toastTime=Math.max(0,toastTime-dt);hitTime=Math.max(0,hitTime-dt);wheelCooldown=Math.max(0,wheelCooldown-dt);const movement=movePlayer(player,world,dt,localInput());if(movement.moving)bob+=dt*movement.speed*1.3;camera.position.set(player.x,player.y+(player.down?.7:1.65),player.z);camera.rotation.set(player.pitch,player.yaw,0);sfx.setListener(player);for(const a of actors){a.age+=dt;const d=ACTORS[a.type];changeFrame(a.sprite,atlas.actor(a.type,a.hitFlash>0&&a.hp>0?'hurt':a.state,a.age,a.duration));a.sprite.position.set(a.x,(a.groundY||0)+a.y+(d.hover&&a.hp>0?d.hover+Math.sin(elapsed*4+a.id)*.11:0),a.z);}for(const n of nests){changeFrame(n.sprite,n.machine?atlas.frame('legacyProps',Math.floor(n.age*5)%4,0):nestFrame(n));n.sprite.scale.y=n.state==='husk'?.65:n.variant===2?3.45:2.9;}for(const c of cases)changeFrame(c.sprite,atlas.frame('pickups',c.open?Math.min(7,Math.floor(c.age*9)):0,2));for(const p of projectiles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.z+=p.vz*dt;p.age+=dt;p.mesh.position.set(p.x,p.y,p.z);changeFrame(p.mesh,atlas.frame('attackVfx',Math.floor(p.age*16)%8,p.row));}for(const w of waves){w.age+=dt;if(w.age<0)continue;w.radius=w.kind==='pool'?1.8:w.age*8;updateWaveVisual(w);}advanceEffects(dt);levelVisuals.update(dt);stationVisuals.update(elapsed,player,paused?null:sfx,world);for(const p of infestation.patches)p.age+=dt;growthVisuals.update();tasks.clock+=dt;taskVisuals.update(camera);updateLights(dt);updateCrewSprites(dt);updateNavigation(dt);drawHud();}
function networkEvent(e){if(e.type==='connecting')$('room-status').textContent='CONNECTING…';if(e.type==='lobby'){refreshRoom();if(!net.active&&running)returnTitle(false);}if(e.type==='error'){$('room-status').textContent=e.message;toast(e.message);refreshRoom(false);}if(e.type==='hostLost'){toast('HOST CONNECTION LOST');returnTitle(false);$('room-status').textContent='HOST CONNECTION LOST / REJOIN FROM THE TITLE SCREEN';}if(e.type==='left'){const m=crew.find(m=>m.id===e.id);if(m?.sprite){scene.remove(m.sprite);m.sprite.material.dispose();}crew=crew.filter(m=>m.id!==e.id);}if(e.type==='start'){const {seed,chapter,keep}=e.settings;$('seed').value=seed;$('theme').value=chapter;setup(seed,chapter,keep);running=true;paused=false;ending=false;$('menu').hidden=true;$('pause').hidden=true;$('ending').hidden=true;$('next').hidden=true;document.body.classList.remove('menu-open');sfx.unlock();sfx.setPaused(false);}if(e.type==='frame')receiveFrame(e.state);}
function refreshRoom(status=true){if(status)$('room-status').textContent=net.code?'ROOM '+net.code+' / '+(net.mode==='coop'?'CO-OP':net.mode==='ffa'?'FREE-FOR-ALL':'RIVAL RECOVERY')+(net.role==='guest'?'\nWAITING FOR HOST':'\nSHARE THIS CODE WITH YOUR CREW'):'';$('room-roster').textContent=net.members.map(m=>PILOTS[m.pilot].name.toUpperCase()+(m.id==='host'?' / HOST':'')).join('\n');$('room-deploy').hidden=net.role!=='host'||!net.peer?.open;$('room-leave').hidden=net.role==='solo';$('host-room').disabled=net.role!=='solo';$('join-room').disabled=net.role!=='solo';}
function returnTitle(leave=true){controller.suspend();controllerMenu.clear();if(mode==='solo'&&running&&!ending)saveCampaign(false);running=false;paused=false;ending=false;shooting=false;keys.clear();document.exitPointerLock?.();if(leave){if(net.role==='host')net.returnToLobby();else net.leave();}sfx.setPaused(true);$('ending').hidden=true;$('pause').hidden=true;$('menu').hidden=false;$('next').hidden=false;document.body.classList.add('menu-open');refreshRoom();refreshSaves();populateChapters();}
function saveCampaign(manual=false,completed=false){if(!ready||mode!=='solo'||!running||player.hp<=0||ending&&!completed)return false;try{saves.save(Number($('save-slot').value),sceneState(),CHAPTERS[chapterIndex].title);if(manual)toast('RECOVERY SAVED');refreshSaves();return true;}catch(e){if(manual)toast('SAVE FAILED / '+e.message);return false;}}
function refreshSaves(){const save=saves.load(Number($('save-slot').value));$('save-description').textContent=save?save.label.toUpperCase()+'\n'+new Date(save.savedAt).toLocaleString()+'\nSCRAP '+save.state.score:'EMPTY RECOVERY SLOT';$('load-save').disabled=!save;$('export-save').disabled=!save;}
function loadCampaign(){controller.suspend();const save=saves.load(Number($('save-slot').value));if(!save)return false;net.leave();const s=save.state;entryLoadout=null;entryScore=0;pilot=s.pilot;$('pilot').value=pilot;$('seed').value=s.seed;$('theme').value=s.chapter;setup(s.seed,s.chapter,false,s.layoutVersion??2);applyState(s);Object.assign(player,s.player,{down:false,dead:false,hurtCooldown:2,vy:0});clearStationOverlap(world,player);Object.assign(arsenal,s.arsenal);score=s.score;localCrew().score=score;running=true;paused=false;ending=false;$('menu').hidden=true;$('pause').hidden=true;$('ending').hidden=true;document.body.classList.remove('menu-open');camera.position.set(player.x,player.y+1.65,player.z);camera.rotation.set(player.pitch,player.yaw,0);sfx.unlock();sfx.setPaused(false);if(mission.complete)finish(true);else{syncMissionProgress();const key=mission.progressKey;mission.progressKey=null;syncMissionProgress();mission.progressKey=key;radio.send({id:'resume-'+chapterIndex,speaker:'ROOK',chapter:CHAPTERS[chapterIndex].title,text:tasks.solved?mission.record?CHAPTERS[chapterIndex].guardian:CHAPTERS[chapterIndex].intro:tasks.objective(),priority:true});}return true;}
$('host-room').onclick=()=>net.create($('pilot').value,$('net-mode').value);$('join-room').onclick=()=>net.join($('room-input').value,$('pilot').value);$('room-deploy').onclick=()=>{campaign=[];entryScore=score=0;entryLoadout=null;start();};$('room-leave').onclick=()=>{net.leave();refreshRoom();};$('leave-game').onclick=()=>returnTitle();$('save-game').onclick=()=>saveCampaign(true);$('load-save').onclick=loadCampaign;$('save-slot').onchange=refreshSaves;$('export-save').onclick=()=>{try{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([saves.export(Number($('save-slot').value))],{type:'application/json'}));a.download='Scrapper-Recovery-Slot-'+(Number($('save-slot').value)+1)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}catch(e){toast(e.message);}};$('import-save').onclick=()=>$('save-file').click();$('save-file').onchange=async()=>{const file=$('save-file').files[0];if(!file)return;try{saves.import(await file.text(),Number($('save-slot').value));refreshSaves();}catch(e){$('save-description').textContent=e.message;}};

function shotTracer(from,to,w){
 emitVisual('tracer',{from:{...from},to:{...to},gun:w.id});
 if(w.mode==='flame'){
  const distance=Math.hypot(to.x-from.x,to.y-from.y,to.z-from.z),life=Math.max(.16,Math.min(.46,distance/22));
  for(let i=0;i<3;i++){const mesh=effectSprite(atlas,0,1,from.x,from.y,from.z,.7,'#ffffff','areaVfx');mesh.material.rotation=(i-1)*.2;scene.add(mesh);effects.push({mesh,age:i*.016,life:life+i*.035,flame:true,tracer:true,from:{...from},to:{x:to.x,y:to.y+(i-1)*.16,z:to.z}});}
  lights.flash(from,'#ffb947',16,.16,13);lights.flash(to,'#ff8e29',12,.22,12);return;
 }
 const row=w.id==='rockets'?3:w.id==='arc'||w.id==='blades'?1:2,size=w.id==='rockets'?.6:w.id==='beam'?.4:.34,mesh=effectSprite(atlas,row,0,from.x,from.y,from.z,size,w.id==='frost'?'#c7faff':'#ffffff');scene.add(mesh);effects.push({mesh,age:0,life:Math.max(.12,Math.min(.5,Math.hypot(to.x-from.x,to.y-from.y,to.z-from.z)/(w.id==='rockets'?38:80))),vfx:row,tracer:true,from:{...from},to:{...to}});
}

function syncMissionProgress(){if(mode==='ffa')return;if(world.puzzle.required===false&&tasks.solved)world.puzzle.solved=true;const bossAlive=actors.some(a=>ACTORS[a.type].tier==='BOSS'&&a.hp>0),key=!tasks.powered?'couplers-'+tasks.taken.length:!tasks.solved?'system-'+tasks.kind:!world.accessCard.taken?'access':!world.puzzle.solved?'relays':!mission.record?'archive':bossAlive?'guardian':'extract';if(mission.progressKey===key)return;const first=!mission.progressKey;mission.progressKey=key;guide.timer=0;if(first)return;const text=key.startsWith('couplers')?tasks.taken.length===2?'Both couplers recovered. Install them on the control deck.':'One coupler recovered. Follow the route to the second.':key.startsWith('system')?tasks.objective()+'. The auxiliary system must be restored before extraction.':key==='access'?CHAPTERS[chapterIndex].system:key.startsWith('relays')?'Blue access secured. Follow the sequence shown on the relay diagram.':key==='archive'?'The grid is online. Recover the archive and choose where its power goes.':key==='guardian'?CHAPTERS[chapterIndex].guardian:storyMessage(chapterIndex,'aftermath',{results:campaign,mission}).text;radio.send({id:'progress-'+chapterIndex+'-'+key,speaker:'ROOK',chapter:CHAPTERS[chapterIndex].title.toUpperCase(),text,priority:true});saveCampaign(false);}
